mkdir -p ~/academy-labs/p1-8/src && cd ~/academy-labs/p1-8 && npm init -y > /dev/null && npm pkg set type=module scripts.build=tsc && printf 'save-exact=true\n' > .npmrc && npm install zod@4.6.7 > /dev/null && npm install -D typescript@5.9.3 @types/node@24.12.2 > /dev/null
cat > tsconfig.json <<'EOF'
{
  "compilerOptions": {
    "strict": true, "target": "ES2023", "module": "NodeNext", "moduleResolution": "NodeNext",
    "types": ["node"], "rootDir": "src", "outDir": "dist"
  },
  "include": ["src"]
