EOF
cat > src/main.ts <<'EOF'
import { createServer } from "node:http";
import { z } from "zod";

const Comment = z.object({ text: z.string().min(1).max(400) });
const comments: string[] = [];

const server = createServer(async (req, res) => {
  if (req.url === "/health") return void res.end("ok");
  if (req.method === "POST" && req.url === "/v1/comments") {
    let body = "";
    for await (const chunk of req) body += chunk;
    const parsed = Comment.safeParse(JSON.parse(body || "{}"));
    if (!parsed.success) return void res.writeHead(400).end("bad comment\n");
    comments.push(parsed.data.text);
    return void res.writeHead(201).end(`${comments.length} comments\n`);
  }
  res.writeHead(404).end();
});

server.listen(8080, () => console.log("listening on :8080"));
process.on("SIGTERM", () => server.close(() => process.exit(0)));
EOF
